window.HOEREN_TESTS[46] = {"id":"computer-und-probleme","name":"Computer und Probleme","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Lisa, hier ist Anna. Mein Laptop ist kaputt. Geht plötzlich nicht mehr an. Nicht verloren und nicht gestohlen, er ist einfach kaputt. Hatte gestern noch gearbeitet — alles weg. Brauche ihn für die Arbeit, kann ich deinen alten ausleihen für drei Tage? Bis Reparatur fertig. Bitte ruf zurück, danke!","gender":"f","q":"Was ist passiert?","opts":["Laptop verloren.","Laptop kaputt.","Laptop gestohlen."],"correct":1},{"transcript":"Liebe Kunden des Computer-Shops Tech-Plus: Wir haben Sonderangebote diese Woche! Laptops 20% billiger, Tablets 30%, Drucker 50% billiger. Aber Vorsicht — Smartphones bleiben zum Normalpreis. Nur bis Samstag das Angebot. Kommen Sie vorbei, Beratung ist kostenlos. Wir freuen uns auf Ihren Besuch im Stadtzentrum. Das Angebot gilt nur diese Woche.","gender":"m","q":"Was ist nicht im Angebot?","opts":["Tablets.","Smartphones.","Drucker."],"correct":1},{"transcript":"Hi Markus, hier ist Tom. Hör mal, mein Internet ist seit gestern weg. Der Techniker kommt erst Mittwoch — das dauert zu lang! Kann ich heute zu dir kommen und schnell E-Mails checken? Wichtige Sachen. Wenn du nicht zu Hause bist, ins Café gehen. Sag bitte Bescheid.","gender":"m","q":"Was möchte Tom?","opts":["Auf den Techniker warten.","Im Café arbeiten.","Bei Markus arbeiten."],"correct":2},{"transcript":"Achtung Computer-Nutzer: Es gibt ein neues Virus, das per E-Mail kommt. Bitte öffnet keine Anhänge von unbekannten Absendern. Auch nicht von Banken — die schicken keine Anhänge. Aktualisiert eure Antiviren-Software. Bei Problemen wendet euch an die IT-Abteilung der Firma. Vielen Dank für Ihre Aufmerksamkeit!","gender":"f","q":"Was sollte man nicht tun?","opts":["Anhänge von Unbekannten öffnen.","E-Mails lesen.","Antivirus benutzen."],"correct":0},{"transcript":"Hi Sara, hier ist Lukas. Ich habe Probleme mit meinem Drucker. Er druckt schon, aber nur halbe Seiten. Neu kaufen wäre gerade zu teuer. Habe Toner gewechselt, hat nicht geholfen. Vielleicht kommt der Service-Mann? Kostet aber 80 Euro. Oder ich kaufe einen neuen — 150 Euro im Angebot. Was meinst du?","gender":"m","q":"Welches Problem hat Lukas?","opts":["Drucker druckt nicht.","Drucker zu teuer.","Drucker druckt nur halbe Seiten."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Computerkurs läuft diese Woche schon bis spät in den Abend."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Jeder hat eine andere Aufgabe. Die Liste ist bei mir schon offen."},{"speaker":"Lukas","gender":"m","text":"Ich programmiere eine App. Sie soll später auf dem Handy laufen."},{"speaker":"Lisa","gender":"f","text":"Daran arbeitest du seit vielen Monaten. Das wird richtig nützlich."},{"speaker":"Lukas","gender":"m","text":"Schreibt noch jemand bei euch lange Texte?"},{"speaker":"Lisa","gender":"f","text":"Nein. Texte schreibt hier keiner."},{"speaker":"Lukas","gender":"m","text":"Du sitzt abends lange an den Bildern von eurer Familie."},{"speaker":"Lisa","gender":"f","text":"Ich bearbeite Fotos und mache sie hell und scharf."},{"speaker":"Lukas","gender":"m","text":"Tom stellt jede Woche etwas Neues ins Netz."},{"speaker":"Lisa","gender":"f","text":"Tom schneidet Videos. Auf seinem Kanal werden die Zuschauer immer mehr."},{"speaker":"Lukas","gender":"m","text":"Sara arbeitet gerade für den Verein am Bildschirm."},{"speaker":"Lisa","gender":"f","text":"Sara designt eine Webseite. Die Farben werden klar und freundlich."},{"speaker":"Lukas","gender":"m","text":"Beantwortet noch jemand bei euch E-Mails?"},{"speaker":"Lisa","gender":"f","text":"Nein. E-Mails sind es auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim sitzt abends mit Kopfhörern bei seinen Freunden."},{"speaker":"Lisa","gender":"f","text":"Tim spielt Online-Spiele. Dabei bleibt er oft lange wach."},{"speaker":"Lukas","gender":"m","text":"Dann speichern wir alles noch vor dem Abendessen."},{"speaker":"Lisa","gender":"f","text":"Ich mache vorher noch schnell eine Kopie."}],"options":[{"letter":"a","text":"Musik produzieren"},{"letter":"b","text":"Videos schneiden"},{"letter":"c","text":"App programmieren"},{"letter":"d","text":"Fotos bearbeiten"},{"letter":"e","text":"Animationen erstellen"},{"letter":"f","text":"Online-Spiele"},{"letter":"g","text":"Texte schreiben"},{"letter":"h","text":"E-Mails beantworten"},{"letter":"i","text":"Webseite designen"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Mein Computer ist so langsam. Kann man da bitte was machen?"},{"speaker":"Techniker","gender":"m","text":"Ja, mehr Arbeitsspeicher oder eine SSD-Festplatte hilft immer."},{"speaker":"Kundin","gender":"f","text":"Was kostet das? Nur RAM oder nur SSD?"},{"speaker":"Techniker","gender":"m","text":"Beides zusammen kostet 200 Euro, mit Einbau und Garantie."},{"speaker":"Kundin","gender":"f","text":"Gut, dann machen Sie beides, bitte heute."}],"q":"Was wird gemacht?","opts":["Beides.","Nur SSD.","Nur RAM."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, mein Tablet ist runtergefallen! Alles voller Risse!"},{"speaker":"Mutter","gender":"f","text":"Oh nein, ist das Display kaputt? Kannst du ohne Tablet leben?"},{"speaker":"Sohn","gender":"m","text":"Nein, ich brauche es für die Schule! Neues kaufen oder reparieren lassen?"},{"speaker":"Mutter","gender":"f","text":"Neues kostet 300, Reparatur nur 150. Was meinst du?"},{"speaker":"Sohn","gender":"m","text":"Dann reparieren lassen, das ist billiger! Danke, Mama!"}],"q":"Was macht der Sohn?","opts":["Neues Tablet kaufen.","Reparieren lassen.","Ohne Tablet leben."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Mein Passwort funktioniert plötzlich nicht mehr."},{"speaker":"IT-Mann","gender":"m","text":"Haben Sie es vergessen? Oder erinnert das System sich falsch?"},{"speaker":"Frau","gender":"f","text":"Nein, vergessen habe ich nichts. Aber das System sagt immer falsch."},{"speaker":"IT-Mann","gender":"m","text":"Dann mache ich etwas: Ich setze es zurück. Neues Passwort kommt per E-Mail."},{"speaker":"Frau","gender":"f","text":"Vielen Dank! Dann warte ich auf die E-Mail."}],"q":"Was macht der IT-Mann?","opts":["Erinnert das Passwort.","Setzt Passwort zurück.","Sagt, nichts zu machen."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Wie lange noch am Computer? Es ist schon spät!"},{"speaker":"Tochter","gender":"f","text":"Nur noch kurz, bis 20 Uhr. Ich mache Hausaufgaben fertig."},{"speaker":"Vater","gender":"m","text":"Bis 18 Uhr wäre besser gewesen. Aber gut, 20 Uhr ist okay."},{"speaker":"Tochter","gender":"f","text":"Und bis 22 Uhr sicher nicht, versprochen, Papa!"},{"speaker":"Vater","gender":"m","text":"Versprochen ist versprochen. Dann Pause, Augen werden müde, und der Rücken auch."}],"q":"Bis wann darf sie?","opts":["18 Uhr.","22 Uhr.","20 Uhr."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Welcher Laptop ist gut fürs Studium? Ich studiere Informatik."},{"speaker":"Verkäuferin","gender":"f","text":"Für Informatik brauchen Sie mindestens 16 GB RAM. 8 GB sind zu wenig."},{"speaker":"Kunde","gender":"m","text":"Und 32 GB? Wäre das nicht besser?"},{"speaker":"Verkäuferin","gender":"f","text":"32 GB brauchen nur Profis. Dieser hier mit 16 GB ist perfekt, 1000 Euro."},{"speaker":"Kunde","gender":"m","text":"Gut, dann nehme ich ihn. Vielen Dank!"}],"q":"Was wird empfohlen?","opts":["16 GB RAM Laptop.","8 GB RAM Laptop.","32 GB RAM Laptop."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Lehmann, einem IT-Experten. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Lehmann, Sie arbeiten als IT-Berater seit 20 Jahren. Was sind die heutigen Probleme der Computer-Nutzer?"},{"speaker":"Lehmann","gender":"m","text":"Sicherheit ist Nummer eins. Die Leute klicken alles an, was per E-Mail kommt. Phishing-Mails sehen heute sehr echt aus, von Banken oder Amazon. Viele fallen darauf rein, verlieren Geld oder Daten."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie?"},{"speaker":"Lehmann","gender":"m","text":"Niemals auf Links in E-Mails klicken — immer direkt zur Webseite gehen. Bank ruft nicht per E-Mail an. Antivirus aktualisieren. Komplizierte Passwörter, anders für jede Seite. Zwei-Faktor-Authentifizierung, immer."},{"speaker":"Reporterin","gender":"f","text":"Wie ist es mit Backups?"},{"speaker":"Lehmann","gender":"m","text":"Sehr wichtig! Viele Leute haben keine Backups. Wenn Festplatte kaputt — alles weg. Fotos, Dokumente, alles. Externe Festplatte oder Cloud — eines davon mindestens. Am besten beides."},{"speaker":"Reporterin","gender":"f","text":"Müssen ältere Menschen Computer lernen?"},{"speaker":"Lehmann","gender":"m","text":"Heute praktisch ja. Banken werden digital, Termine online, Behörden digital. Wer nicht mit Computer umgehen kann, hat Probleme. Aber Kurse helfen — die VHS bietet gute Sachen für Senioren."},{"speaker":"Reporterin","gender":"f","text":"Und Kinder am Computer?"},{"speaker":"Lehmann","gender":"m","text":"Zeitlich begrenzen, eine Stunde pro Tag bei Kleinen reicht. Inhalte kontrollieren. Aber komplett verbieten ist falsch — die Welt ist digital, sie müssen das lernen. Balance ist wichtig."}],"items":[{"q":"Banken rufen oft per E-Mail an.","correct":"nein"},{"q":"Phishing-Mails sind ein großes Problem heute.","correct":"ja"},{"q":"Backups sind sehr wichtig.","correct":"ja"},{"q":"Ältere Menschen brauchen heute keine Computer-Kenntnisse.","correct":"nein"},{"q":"Kinder sollten komplett vom Computer ferngehalten werden.","correct":"nein"}]}]};
